-- No name/parent changes. No lookup-function changes.

\set ON_ERROR_STOP on

BEGIN;
SET LOCAL statement_timeout = '30min';
SET LOCAL lock_timeout = '30s';

CREATE TABLE IF NOT EXISTS system.repair_township_overlap_final_admin_areas_20260724 (
    id bigint PRIMARY KEY,
    role text NOT NULL,
    canonical_name text NOT NULL,
    parent_id bigint,
    admin_level_id bigint NOT NULL,
    admin_area_type_id bigint,
    is_active boolean NOT NULL,
    deleted_at timestamptz,
    geom geometry(MultiPolygon, 4326) NOT NULL,
    geom_hash text NOT NULL,
    area_m2 double precision NOT NULL,
    updated_at timestamptz,
    repaired_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS system.repair_township_overlap_final_apply_log_20260724 (
    id bigserial PRIMARY KEY,
    loser_id bigint NOT NULL,
    area_before_m2 double precision NOT NULL,
    area_after_m2 double precision NOT NULL,
    area_removed_m2 double precision NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now()
);

