    id, role, canonical_name, parent_id, admin_level_id, admin_area_type_id,
    is_active, deleted_at, geom, geom_hash, area_m2, updated_at
)
SELECT aa.id, 'geom_changed', aa.canonical_name, aa.parent_id, aa.admin_level_id,
       aa.admin_area_type_id, aa.is_active, aa.deleted_at, aa.geom,
