UPDATE core.core_admin_areas aa
SET geom = ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Difference(aa.geom, r.removal)), 3)),
    updated_at = now()
FROM ov_removal r
WHERE aa.id = r.id;

INSERT INTO system.repair_township_overlap_final_apply_log_20260724 (
    loser_id, area_before_m2, area_after_m2, area_removed_m2
)
SELECT b.id,
       ST_Area(ST_Transform(b.geom, 6933)),
       ST_Area(ST_Transform(aa.geom, 6933)),
       ST_Area(ST_Transform(b.geom, 6933)) - ST_Area(ST_Transform(aa.geom, 6933))
FROM system.repair_township_overlap_final_admin_areas_20260724 b
JOIN core.core_admin_areas aa ON aa.id = b.id;

DO $$
DECLARE
  v_bad integer;
BEGIN
  SELECT count(*) INTO v_bad
  FROM core.core_admin_areas aa WHERE aa.id IN (5125, 6288, 6331, 6336, 6338, 6390, 6410, 6412, 6414, 6416, 6434, 6569, 6599, 6620, 7233, 7295, 7300, 7309, 7323, 7526)
    AND (aa.geom IS NULL OR ST_IsEmpty(aa.geom) OR NOT ST_IsValid(aa.geom)
         OR ST_SRID(aa.geom) <> 4326
         OR GeometryType(aa.geom) NOT IN ('POLYGON','MULTIPOLYGON'));
  IF v_bad <> 0 THEN
    RAISE EXCEPTION 'Invalid geometry after overlap repair on % row(s)', v_bad;
  END IF;
END $$;

